import json,re,collections
d=json.load(open('/tmp/reach.json'))
tot=0; files=0; per={}
for m in d['unrooted']:
    n=0
    for l in open(d['paths'][m],encoding='utf-8',errors='replace'):
        if re.match(r'\s*set_option\s+(maxHeartbeats|synthInstance\.maxHeartbeats|maxRecDepth)', l): n+=1
    if n: files+=1; tot+=n; per[m]=n
print("unrooted files with raised heartbeat/recDepth options:", files, "total options:", tot)
top=sorted(per.items(), key=lambda x:-x[1])[:10]
for m,n in top: print(f"   {n:3d}  {m.split('.')[-1]}")
# same for rooted, for comparison
rt=0; rf=0
for m in d['reachable']:
    n=sum(1 for l in open(d['paths'][m],encoding='utf-8',errors='replace')
          if re.match(r'\s*set_option\s+(maxHeartbeats|synthInstance\.maxHeartbeats|maxRecDepth)', l))
    if n: rf+=1; rt+=n
print("rooted:", rf, "files,", rt, "options  (over", len(d['reachable']), "modules)")
EOF
